#pragma once

// Parameters for the rl_supermimic runner: SuperMimic general motion tracker (SCL/Experiments/supermimic_multi,
// SUPERMIMIC_ROBOT=t800) driven by the terminator-teleop UDP reference stream. Config generated by
// SCL/Experiments/t800_port/runner_test/make_runner_config.py from the training robot spec (no hand transcription).

#include <glog/logging.h>
#include <Eigen/Dense>
#include <map>
#include <string>
#include <vector>

#include "basic_param/basic_param.h"
#include "parameter/parameter_loader.h"

namespace data {

class SuperMimicJointConfig {
 public:
  double q_default = 0.0;
  double kp = 50.0;
  double kd = 1.0;
  double tau_max = 100.0;  // training IdealPd effort limit
  double q_min = -6.5;
  double q_max = 6.5;
  double action_scale = 0.25;
};

class RlSuperMimicParam : public BasicParam {
 public:
  RlSuperMimicParam(std::string_view tag = "rl_supermimic");

  DEFINE_PARAM_SCOPE(scope_);

  // Policy: single MNN input = [obs history (obs_history_length * (3*nj + 6)) | goal (future_frames * (2*nj + 10))]
  std::string policy_path;
  std::vector<std::string> policy_joint_names;  // policy / training order (MJCF J00..J24)
  std::vector<std::string> packet_joint_names;  // UDP packet order (terminator-teleop deploy_config, Isaac)
  int obs_history_length = 10;
  int future_frames = 10;
  std::map<std::string, SuperMimicJointConfig> joints;

  // Reference (see reference_buffer.h)
  int udp_port = 47801;  // NOT 47800: rl_teleop keeps that socket bound after its mode exits
  double ref_delay_s = 0.2;
  double ref_sigma_frames = 1.5;
  double ref_stale_s = 0.5;
  double ref_blend_in_s = 1.5;
  double ref_blend_out_s = 1.0;
  double ref_height_calib_s = 1.0;
  double stand_height = 1.0165;
  double entry_blend_s = 2.0;

  // Robot state conventions (same meaning as in rl_teleop; see its param header for the history)
  // "heading_fixed": tilt RELATIVE to the entry pose (cancels an IMU mount offset, but also bakes in any real lean
  //                  at entry as "upright": 2026-11-04 robot entered at 7.5 deg raw tilt -> policy saw a steady 9.4 deg roll)
  // "absolute":      tilt straight from the IMU, only the entry heading removed. Correct when the IMU is mounted level.
  std::string robot_rot_mode = "heading_fixed";
  bool imu_ang_vel_world = false;  // the SDK delivers a BODY-frame gyro (sim and robot)

  // Safety
  double action_sanity_limit = 20.0;  // rad on |action_scale * a| (or non-finite) -> latch. GARBAGE detector only:
                                      // healthy runs reach 4.05 rad (beyond-range ankle targets)
  double action_clip = 100.0;
  bool torque_limit = true;           // per-joint |tau| <= tau_max (as training)
  bool clamp_targets_to_joint_range = false;  // training did NOT clamp targets; see runner .cc
  // Torque-equivalent target split: the position target SENT is clamped inside [q_min + m, q_max - m] and the cut-off
  // part goes as feed-forward torque kp * (q_des - q_sent) -> identical PD torque, but no out-of-range position ever
  // reaches the parallel-ankle converter (a fitted model, invalid past the linkage range; the policy aims ankles 1-3
  // rad past the stop on 15-85% of ticks). Applied after the torque limit.
  bool range_excess_as_torque = true;
  double range_margin = 0.02;
  // 2026-11-05 robot 4 Hz ankle bounce. (1) One-pole low-pass on the policy joint targets (1.0 = off), as the
  // hardware-proven rl_teleop (action_lpf_alpha 0.5): explicit PD on hardware tracks action chatter faithfully.
  // last_action in the obs stays RAW (training convention). (2) Ankle joint velocity for the OBSERVATION from the
  // 50 Hz position difference instead of the parallel-ankle converter velocity (robot: ankle-roll qd 1.9x the true
  // rate, corr 0.68; sim 0.97). Motor PD, torque limit and flight log keep the raw velocity.
  double action_lpf_alpha = 1.0;
  bool qd_from_q_ankles = false;
  // 2026-11-05: one-pole low-pass on the LEG joint velocity observation (HIP/KNEE/ANKLE joints), at the 50 Hz
  // policy rate: qd_f += alpha * (qd - qd_f). 1.0 = off. Offline ablation of the robot bounce: the policy's ankle
  // action chatter is driven by high-frequency content in the leg qd observation (robot ankle roll qd carries
  // 3-4 rad/s not present in the position signal); 5 Hz low-pass cut it ~60%. alpha 0.47 ~ 5 Hz.
  double qd_obs_lpf_alpha = 1.0;
  double fall_up_z = 0.5;             // base up-axis z below this ...
  int fall_ticks = 25;                // ... for this many ticks -> stop the policy, damp in place
  // Entry check (2026-11-04 robot vibration: walk handed over mid-step, R ankle pitch 0.43 rad off default ->
  // the policy thrashed). Enter() refuses unless every leg pitch/roll joint is within entry_leg_tol of its default
  // and the base is quiet. Sim walk-mode entries: max 0.037 rad off.
  bool entry_check = true;
  double entry_leg_tol = 0.15;        // rad, HIP_PITCH / KNEE / ANKLE_PITCH / ANKLE_ROLL
  double entry_gyro_max = 0.5;        // rad/s, |body angular velocity|
  double entry_tilt_max_deg = 10.0;   // raw IMU tilt
  bool entry_force_refuse = false;    // TEST ONLY: always refuse (to observe the executor's behaviour)
};

}  // namespace data

namespace YAML {
template <>
struct convert<data::SuperMimicJointConfig> {
  static bool decode(const Node& node, data::SuperMimicJointConfig& v) {
    if (node["q_default"]) v.q_default = node["q_default"].as<double>();
    if (node["kp"]) v.kp = node["kp"].as<double>();
    if (node["kd"]) v.kd = node["kd"].as<double>();
    if (node["tau_max"]) v.tau_max = node["tau_max"].as<double>();
    if (node["q_min"]) v.q_min = node["q_min"].as<double>();
    if (node["q_max"]) v.q_max = node["q_max"].as<double>();
    if (node["action_scale"]) v.action_scale = node["action_scale"].as<double>();
    return true;
  }
};
}  // namespace YAML
